uniform float ember_speed : 0.05 .. 2.0 = 0.4;
uniform float spark_rate : 0.0 .. 3.0 = 0.6;
uniform float spark_life : 0.05 .. 0.5 = 0.18;
uniform float ember_brightness : 0.1 .. 1.0 = 0.6;
uniform float spark_brightness : 0.2 .. 1.5 = 1.0;
uniform float wind : 0.0 .. 1.0 = 0.15;
uniform vec3 base_color : color = 1.0, 0.35, 0.08;

state fixed ph_ember;
state fixed ph_wind;
state int spark_count;
state fixed spark_pos[8];
state fixed spark_vel[8];
state fixed spark_age[8];
state fixed spark_max_age[8];
state bool inited;

void update() {
  ph_ember = fract(ph_ember + fixed(dt * ember_speed));
  ph_wind = fract(ph_wind + fixed(dt * wind * 0.3));

  if (!inited) {
    spark_count = 0;
    inited = true;
  }

  float spawn_chance = dt * spark_rate * 8.0;
  if (hash(float(frame)) < spawn_chance && spark_count < 8) {
    int idx = spark_count;
    spark_pos[idx] = fixed(0.0);
    spark_vel[idx] = fixed(2.0 + hash(float(frame) * 1.7) * 4.0);
    spark_age[idx] = fixed(0.0);
    spark_max_age[idx] = fixed(spark_life);
    spark_count = spark_count + 1;
  }

  for (int i = 0; i < 8; i = i + 1) {
    if (i < spark_count) {
      spark_age[i] = spark_age[i] + fixed(dt);
      spark_pos[i] = spark_pos[i] + spark_vel[i] * fixed(dt);
      if (spark_age[i] > spark_max_age[i] || spark_pos[i] > fixed(1.0)) {
        spark_count = spark_count - 1;
        if (i < spark_count) {
          spark_pos[i] = spark_pos[spark_count];
          spark_vel[i] = spark_vel[spark_count];
          spark_age[i] = spark_age[spark_count];
          spark_max_age[i] = spark_max_age[spark_count];
        }
      }
    }
  }
}

vec3 shade(Led led) {
  fixed s = fixed(led.s);
  fixed h = fixed(led.uv.y);

  fixed ember_wave = sin(h * fixed(12.0) + ph_ember) * fixed(0.5) + fixed(0.5);
  fixed wind_wobble = sin(s * fixed(8.0) + ph_wind) * fixed(wind * 0.3);
  fixed ember_phase = fract(s * fixed(3.0) - ph_ember + wind_wobble * fixed(0.2));

  fixed ember_intensity = ember_wave * (fixed(1.0) - ember_phase) * fixed(ember_brightness);
  ember_intensity = ember_intensity * ember_intensity;

  vec3 c = base_color * float(ember_intensity);

  for (int i = 0; i < 8; i = i + 1) {
    if (i < spark_count) {
      fixed d = abs(s - spark_pos[i]);
      if (d < fixed(0.08)) {
        fixed life_frac = spark_age[i] / spark_max_age[i];
        fixed spark_intensity = (fixed(1.0) - life_frac) * (fixed(1.0) - d * fixed(12.5));
        spark_intensity = spark_intensity * spark_intensity * fixed(spark_brightness);

        fixed hue_shift = (fixed(1.0) - life_frac) * fixed(0.15);
        fixed sat = fixed(1.0) - life_frac * fixed(0.5);
        vec3 spark_col = hsv2rgb(fixed(0.08) + hue_shift, sat, fixed(1.0));
        c = c + spark_col * float(spark_intensity);
      }
    }
  }

  return clamp(c, vec3(0.0), vec3(1.0));
}

